package export_ohrats_rc_process_policy

import (
	"strings"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_process_types"
	"wit_component/policy"
)

// AuthorizeStart admits a start request and returns the normalized plan.
// Execute scope is required and execution id, channel/lifetime pairing,
// execution mode, working directory, environment, and terminal are
// validated before the plan is returned.
func AuthorizeStart(request ohrats_rc_process_types.StartRequest) witTypes.Result[ohrats_rc_process_types.StartPlan, string] {
	if !request.Principal.CanExecute {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string]("execute scope required")
	}
	if err := policy.ValidateToken(request.ExecutionId, 128, "execution id"); err != nil {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string](err.Error())
	}
	if err := policy.ValidateChannel(request); err != nil {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string](err.Error())
	}
	if err := policy.ValidateMode(request.Mode); err != nil {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string](err.Error())
	}
	if request.Cwd.IsSome() && strings.ContainsRune(request.Cwd.Some(), 0) {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string]("invalid process working directory")
	}
	if err := policy.ValidateEnvironment(request.Environment); err != nil {
		return witTypes.Err[ohrats_rc_process_types.StartPlan, string](err.Error())
	}
	terminal := witTypes.None[ohrats_rc_process_types.Terminal]()
	if request.Terminal.IsSome() {
		normalized, err := policy.NormalizeTerminal(request.Terminal.Some())
		if err != nil {
			return witTypes.Err[ohrats_rc_process_types.StartPlan, string](err.Error())
		}
		terminal = witTypes.Some[ohrats_rc_process_types.Terminal](normalized)
	}
	return witTypes.Ok[ohrats_rc_process_types.StartPlan, string](ohrats_rc_process_types.StartPlan{
		Mode:                   request.Mode,
		Cwd:                    request.Cwd,
		Environment:            request.Environment,
		Terminal:               terminal,
		ScrollbackBytes:        4 << 20,
		StdinChunkBytes:        1 << 20,
		AuthorizationTimeoutMs: 15_000,
		TerminateGraceMs:       350,
		ReattachGraceMs:        60_000,
		MaxRuntimeMs:           request.MaxRuntimeMs,
	})
}

// AuthorizeAccess requires execute scope and either owner authority or
// ownership of the target process.
func AuthorizeAccess(request ohrats_rc_process_types.AccessRequest) witTypes.Result[witTypes.Unit, string] {
	if err := policy.AuthorizeAccess(request); err != nil {
		return witTypes.Err[witTypes.Unit, string](err.Error())
	}
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

// NormalizeResize authorizes the request and validates the terminal size.
func NormalizeResize(request ohrats_rc_process_types.ResizeRequest) witTypes.Result[ohrats_rc_process_types.TerminalSize, string] {
	if err := policy.AuthorizeAccess(request.Access); err != nil {
		return witTypes.Err[ohrats_rc_process_types.TerminalSize, string](err.Error())
	}
	if !policy.ValidTerminalDimension(request.Cols) || !policy.ValidTerminalDimension(request.Rows) {
		return witTypes.Err[ohrats_rc_process_types.TerminalSize, string]("invalid terminal size")
	}
	return witTypes.Ok[ohrats_rc_process_types.TerminalSize, string](ohrats_rc_process_types.TerminalSize{
		Cols: request.Cols,
		Rows: request.Rows,
	})
}

// AuthorizeSignal authorizes the request and forwards the requested signal.
func AuthorizeSignal(request ohrats_rc_process_types.SignalRequest) witTypes.Result[ohrats_rc_process_types.Signal, string] {
	if err := policy.AuthorizeAccess(request.Access); err != nil {
		return witTypes.Err[ohrats_rc_process_types.Signal, string](err.Error())
	}
	return witTypes.Ok[ohrats_rc_process_types.Signal, string](request.Signal)
}
